#include "syspulse/native/maintenance.hpp"
#include <iostream>
#include <thread>
#include <cstdlib>
#include <unistd.h>
using namespace syspulse::native;
int count=0;void check(bool b,const char* s){++count;if(!b){std::cerr<<s<<'\n';std::exit(1);}}
Result run(Job& j,Command c){check(j.start(c),"start command");for(int i=0;i<500;++i){if(auto r=j.poll())return *r;std::this_thread::sleep_for(std::chrono::milliseconds(10));}std::exit(2);}
int main(){check(!commandFor(Operation::StopService,"--help.service"),"option injection");check(!commandFor(Operation::StartService,"evil;rm.service"),"shell injection");check(!commandFor(Operation::StartService,"../x.service"),"path injection");check(!commandFor(Operation::Clean,"x.service"),"extra parameter");auto c=commandFor(Operation::Clean);check(c&&c->admin&&c->exe=="/usr/bin/pkexec"&&c->args==std::vector<std::string>{"/usr/bin/apt-get","autoclean"},"fixed clean");c=commandFor(Operation::Refresh);check(c&&c->args.back()=="update","fixed update");c=commandFor(Operation::StopService,"example.service");check(c&&!c->admin&&c->args.back()=="example.service"&&c->args[0]=="--user","user scope");auto s=parseServices("example.service loaded active running description\nsecond.service loaded inactive dead description\n");check(s.size()==2&&s[1].state=="inactive","unit parser");check(parseServices("example.service loaded active running\nexample.service loaded active running\n").empty(),"duplicate unit");Job j;check(!j.start({"/tmp/untrusted",{},false}),"untrusted executable");check(!j.start({"/usr/bin/printf",{"%s","literal; not shell"},false}),"arbitrary trusted executable refused");check(!j.start({"/usr/bin/false",{},false}),"unapproved command refused");auto r=run(j,*commandFor(Operation::Audit));check(r.code==0,"actual dpkg audit");c=commandFor(Operation::PreviewClean);check(c&&c->admin&&c->args==std::vector<std::string>{"/usr/bin/apt-get","-s","autoclean"},"fixed authorized simulation");if(getuid()==0){check(!j.start(*c),"root GUI admin refused");check(!j.start({"/usr/bin/apt-get",{"-s","autoclean"},false}),"unapproved bypass refused");}std::cout<<count<<" maintenance checks passed\n";}
